"""Actual protected PDF downloads for already-issued immutable legacy snapshots."""
import hashlib,json,os,requests,tempfile,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
import test_contract_package as package
class ScopedDocumentPdf(package.ContractPackage):
 def test_existing_proposal_pdf_exact_snapshot_owner_guest_and_browser_download(self):
  oid,docs=self.prepare_documents();proposal=docs[0];snapshot=json.loads(proposal['input_snapshot']);link=self.create_link(oid,[proposal],False);self.assertEqual(link.status_code,200,link.text);guest,x=self.exchange(link.json()['url'].split('#token=')[1]);url=self.base+'/prospect-api.php?r=pdf&id='+str(proposal['id']);self.assertEqual(guest.get(url).status_code,403);self.consent(guest,x);self.assertTrue(guest.get(self.base+'/prospect-api.php?r=documents').json()['documents'][0]['pdf_available']);pdf=guest.get(url);self.assertEqual(pdf.status_code,200,pdf.text[:100] if pdf.status_code!=200 else '');self.assertEqual(pdf.headers['Content-Type'],'application/pdf');self.assertIn('.pdf',pdf.headers['Content-Disposition']);self.assertEqual(pdf.headers['X-Neuro-Source-Hash'],proposal['generated_hash']);self.assertEqual(pdf.headers['X-Neuro-PDF-SHA256'],hashlib.sha256(pdf.content).hexdigest());self.assertTrue(pdf.content.startswith(b'%PDF-'));self.assertIn(b'/FontFile2',pdf.content);self.assertIn(b'/Subtype /Image',pdf.content);owner=self.owner.get(self.base+'/lifecycle-api.php?mode=owner&r=documents/'+str(proposal['id'])+'/pdf');self.assertEqual(owner.content,pdf.content);assets=self.f.sql('SELECT * FROM nd_lc_pdf_assets WHERE binding_id=?',params=[proposal['id']]);self.assertEqual(len(assets),1);self.assertIsNone(assets[0]['owner_reviewed_at']);self.assertEqual(assets[0]['source_hash'],proposal['generated_hash']);self.assertEqual(assets[0]['checksum'],hashlib.sha256(pdf.content).hexdigest())
  data=self.owner_data();data['bank']='SYNTHETIC changed current bank must not replace issued snapshot';old=self.cget()['owner'];self.assertEqual(self.ctp('owner',data=data,prior_id=int(old['id']) if old else 0,reviewed=True).status_code,200);self.assertEqual(guest.get(url).content,pdf.content)
  with tempfile.TemporaryDirectory() as folder:
   path=Path(folder)/'proposal.pdf';path.write_bytes(pdf.content);text=subprocess.check_output(['pdftotext',str(path),'-'],text=True);self.assertIn(snapshot['rendered']['title'],text.replace('\n',' '));self.assertIn('Коммерческое предложение',text);self.assertIn('Страница 1 /',text);self.assertNotIn('{{',text);self.assertNotIn('SYNTHETIC changed current bank',text);self.assertNotIn('00_INTERNAL_GUIDE',text)
   with sync_playwright() as pw:
    browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=browser.new_page(viewport={'width':375,'height':812});page.goto(link.json()['url']);page.get_by_role('checkbox').check();page.get_by_role('button',name='Продолжить к документам',exact=True).click();download_link=page.get_by_role('link',name='Скачать PDF',exact=True);download_link.wait_for();self.assertEqual(page.get_by_role('button',name='Скачать точный текст',exact=True).count(),0);self.assertEqual(page.get_by_role('button',name='Загрузить копию на проверку владельцу',exact=True).count(),0)
    with page.expect_download() as downloaded:download_link.click()
    out=downloaded.value;self.assertTrue(out.suggested_filename.endswith('.pdf'));out.save_as(str(Path(folder)/'browser.pdf'));self.assertEqual((Path(folder)/'browser.pdf').read_bytes(),pdf.content);browser.close()
  self.assertEqual(guest.get(self.base+'/prospect-api.php?r=pdf&id='+str(docs[1]['id'])).status_code,404);self.assertEqual(requests.get(url).status_code,401);self.assertEqual(self.own('revoke',id=link.json()['id'],confirm=True).status_code,200);self.assertEqual(guest.get(url).status_code,401)
 def test_pdf_integrity_and_expiry_are_enforced(self):
  oid,docs=self.prepare_documents();b=docs[0];link=self.create_link(oid,[b],False).json();g,x=self.exchange(link['url'].split('#token=')[1]);self.consent(g,x);url=self.base+'/prospect-api.php?r=pdf&id='+str(b['id']);snapshot=json.loads(b['input_snapshot']);snapshot['rendered']['description']='SYNTHETIC tampered content';self.f.sql('UPDATE nd_lc_document_bindings SET input_snapshot=? WHERE id=?',params=[json.dumps(snapshot,ensure_ascii=False),b['id']]);self.assertEqual(g.get(url).status_code,409);self.f.sql('UPDATE nd_lc_document_bindings SET input_snapshot=? WHERE id=?',params=[b['input_snapshot'],b['id']]);self.f.sql('UPDATE nd_lc_prospect_links SET expires_at=0 WHERE id=?',params=[link['id']]);self.assertEqual(g.get(url).status_code,401)
for name in dir(package.ContractPackage):
 if name.startswith('test_'):setattr(ScopedDocumentPdf,name,None)
